class MessageStructureDecoder(object):

    @staticmethod
    def get_structure_for_message(sack_types_dat_file, message_hex_id, message_name):
        """
        :param sack_types_dat_file: path for 'types.dat' file
        :param message_hex_id: string - message hex_id
        :param message_name: string - full msg filename
        :return: dict - message
        return_example:
        {'message_name': 'UEC_PMI_TICKET_IND_MSG',
        'message_fields':
        {u'ueCounter': {'length': 40, 'offset': 1156},
        u'paddingInitialDownLinkRrcMessage2': {'length': 2, 'offset': 20}
        ...},
        'total_length': 1208,
        'message_hex_id': '426A'
        }
        """
        message_fields = {}
        length_position = 8
        field_name_position = 3
        offset_position = 7
        message_structure = {'message_hex_id': message_hex_id,
                             'message_name': message_name,
                             'message_fields': {}}

        with open(sack_types_dat_file, mode='rb') as data_file:
            for line in data_file:
                line = line.decode('latin1').strip()
                if message_hex_id in line:
                    single_substructure = line.split(',')
                    if message_name in line:
                        message_structure['total_length'] = int(single_substructure[length_position])
                        continue
                    if not single_substructure[field_name_position] in message_fields:
                        message_fields[single_substructure[field_name_position]] = (
                            {'offset': int(single_substructure[offset_position]),
                             'length': int(single_substructure[length_position])})
            message_structure['message_fields'] = message_fields
        return message_structure

    @staticmethod
    def get_structures_for_all_messages(sack_types_dat_file):
        """
        :param sack_types_dat_file: path for 'types.dat' file
        :return: dict - messages structure, where key is hex_msg_id
        return_example:
        {'UEC_PMI_TICKET_IND_MSG':{
        'message_fields':
        {u'ueCounter': {'length': 40, 'offset': 1156},
        u'paddingInitialDownLinkRrcMessage2': {'length': 2, 'offset': 20}
        ...},
        'total_length': 1208,
        'hex_id': '426A'
        },'API_SET_BURST_OFFSET_RESP_MSG':{
        'message_fields':
        {u'transactionId': {'length': 4, 'offset': 16},
        u'offset': {'length': 4, 'offset': 56},
        ...},
        'total_length': 60,
        'hex_id': u'2C81'
        },
        ...}
        """
        length_position = 8
        field_name_position = 3
        offset_position = 7
        messages_structures = {}

        with open(sack_types_dat_file, mode='rb') as data_file:
            actual_msg = ''
            for line in data_file:
                line = line.decode('latin1').strip()
                single_substructure = line.split(',')
                if single_substructure[3] == u'' and single_substructure[4] != u'':
                    messages_structures[single_substructure[4]] = {'hex_id': single_substructure[2],
                                                                   'total_length': int(single_substructure[length_position]),
                                                                   'message_fields': {}}
                    actual_msg = single_substructure[4]
                    continue
                if actual_msg and not single_substructure[field_name_position].lower() in messages_structures[actual_msg]['message_fields']:
                    messages_structures[actual_msg]['message_fields'][single_substructure[field_name_position].lower()]\
                        = ({'offset': int(single_substructure[offset_position]),
                            'length': int(single_substructure[length_position])})
        return messages_structures
